/**
 * Bài 22 — 困ったこと (Chuyện phiền) · TIẾP SAU SÁCH, cấp N4 (xem ../SOAN-BAI.md mục 8). Bài thứ hai của chặng 21–25
 * (Bài 25 = thi thử N4).
 * Người học đã xong Bài 1–15 (ポイント 1–124), Bài 16 (thể khả năng, thể ý chí, ～つもり, ～予定), Bài 17 (～ば, ～なら, ～し,
 * ～すぎる, ～やすい・にくい), Bài 18 (～てあげる・くれる・もらう, ～ておく, ～てある), Bài 19 (～てしまう, ～てみる, ～ところ — kể cả
 * Vたところ "vừa mới xong", ～のに), Bài 20 (～そう, ～ようだ・みたい, ～らしい, ～かもしれない, ～はず) và Bài 21 (～ために, ～ように,
 * ～ようになる・ようにする, ～ことにする・ことになる). KHÔNG dạy lại — chỉ dùng lại trong câu (ghi "ôn: Bài X").
 *
 * Ngữ pháp (N4) — nhóm "bị người khác làm gì · việc được làm ra · toàn là / vừa mới": ① cách chia THỂ BỊ ĐỘNG (受身形) đủ 3 nhóm
 * + bẫy (言う → 言われる, 待つ → 待たれる, nhóm 2 trùng hình thức với thể khả năng, 来る → 来られる, する → される) · ② bị động
 * TRỰC TIẾP: A は B に V(ら)れる (先生に褒められる) · ③ bị động SỞ HỮU: A は B に N を V(ら)れる (足を踏まれる, 財布を盗まれる) ·
 * ④ bị động GIÁN TIẾP = bị PHIỀN (迷惑の受身): 雨に降られる, 赤ちゃんに泣かれる, 隣の人に騒がれる · ⑤ bị động của VẬT / SỰ KIỆN:
 * N が (場所) で 開かれる・行われる, 建てられる, 輸出される, ～によって (người tạo ra: 発明・発見・書く・建てる), ～と言われている ·
 * ⑥ ～ばかり: N ばかり · V て ばかり いる · V た ばかり + BẢNG Vたばかり ↔ Vたところ (Bài 19) ↔ だけ・しか.
 * Thể sai khiến (させる), thể bị động sai khiến (させられる) để Bài 23; kính ngữ dạng られる (先生が来られる) để Bài 24.
 * Từ vựng: 48 từ N4 (một số N3 có ghi cấp): người khác làm gì với mình, chuyện phiền ngoài đường – trên tàu, chuyện phiền ở nhà –
 * ký túc xá, sự kiện & đồ vật, "toàn là / vừa mới". Từ đã học ở Bài 1–21 (怒る, しかる, 盗む, 泥棒, 警察, お巡りさん, 届ける, 壊す,
 * 頼む, 喜ぶ, 驚く, 迷惑, うるさい, 隣, 傘, 財布, 引っ越しする, 入学する, 慣れる, 我慢する, 管理人…) KHÔNG lặp lại — gặp trong câu
 * thì coi như ôn.
 * Chữ Hán mới (15): 踏 盗 犯 捕 被 害 届 誘 招 騒 驚 喜 輸 訳 鳴 (N3 theo các bảng tham khảo phổ biến; một số bảng xếp 踏・被 ở
 * N2 — JLPT không công bố danh sách chữ chính thức) — không trùng hanTu.ts, hanTu16–21.ts, hanLop.ts, bảng chữ Bài 1–21.
 * Thẻ chữ Hán: hanTu22.ts (HAN_TU_22).
 * Hội thoại, câu ví dụ, bài đọc, kịch bản nghe: VIẾT MỚI 100%, không chép giáo trình/đề thi nào.
 *
 * Nhân vật (giới tính quyết định giọng đọc, theo sách p.14): nữ = パク, ワン, アンナ, メアリー, マリヤム, 山口, 木村, リン, 鈴木 ·
 * nam = マルコ, ダニエル, ナタポン, カルロス, 西川, 本田先生, 小林店長.
 * {本田先生|ほんだせんせい} (nam, role 'examiner' / ja-nam) — giáo viên tiếng Nhật của lớp.
 * {小林店長|こばやしてんちょう} (nam, role 'examiner' / ja-nam) — chủ quán ひまわり{食堂|しょくどう} nơi ナタポン làm thêm (Bài 16).
 * {西川|にしかわ} (nam, người Nhật, bạn của nhóm — role 'examiner' trong hội thoại ③′ để khác giọng với カルロス 'b').
 * Nối tiếp các bài trước: món cà ri Thái của ナタポン vừa vào thực đơn (Bài 21); アンナ mới chuyển vào ký túc xá; マルコ chạy bộ
 * mỗi sáng (Bài 21).
 * Người MỚI của bài này (không tên riêng):
 *  - {寮|りょう}の{管理人|かんりにん}さん (hội thoại ②′) — nam, role 'b' / giọng ja-nam.
 *  - {駅員|えきいん}さん (nghe Bài 2) — nam, ja-nam · {係|かかり}の{人|ひと} ở bảo tàng (nghe Bài 4) — nữ, ja-nu.
 * Hội thoại: role 'a'/'c' = giọng nữ, 'b'/'examiner' = giọng nam. Nghe: 'ja-nu' = nữ, 'ja-nam' = nam.
 * Hình: tên trong scripts/hinh/fluent-catalog.json (Fluent Emoji).
 */
import type { Block, Ex, Lesson } from '@/components/sach-hoc/types';

const E = (en: string, ro: string, vi: string): Ex => ({ en, ro, vi });

/**
 * Đáp án gõ tay: viết một lần bằng {漢字|かな}, hàm sinh đủ cách viết chữ Hán / kana
 * (máy chấm đã tự bỏ dấu câu, dấu cách và đổi chữ số toàn khổ). Phần tử đầu = dạng
 * toàn chữ Hán, là đáp án hiển thị.
 */
const V = (...xs: string[]): string[] => {
  const out = new Set<string>();
  for (const x of xs) {
    const slots = x
      .split(/(\{[^|}]+\|[^}]+\})/)
      .filter(Boolean)
      .map((p) => {
        const m = /^\{([^|}]+)\|([^}]+)\}$/.exec(p);
        return m ? [m[1], m[2]] : [p];
      });
    const n = slots.filter((s) => s.length > 1).length;
    if (n <= 8) {
      let acc = [''];
      for (const s of slots) acc = acc.flatMap((a) => s.map((c) => a + c));
      acc.forEach((a) => out.add(a));
    } else {
      out.add(slots.map((s) => s[0]).join(''));
      out.add(slots.map((s) => s[s.length - 1]).join(''));
      slots.forEach((s, i) => {
        if (s.length > 1) out.add(slots.map((t, j) => (j === i ? t[1] : t[0])).join(''));
      });
    }
  }
  return [...out];
};

type Line = [who: string, role: 'a' | 'b' | 'c' | 'examiner' | 'candidate', text: string, ro: string, vi: string];
const DL = (title: string, lines: Line[]): Block => ({
  t: 'dialogue',
  title,
  lines: lines.map(([who, role, text, ro, vi]) => ({ who, role, text, ro, vi })),
});

